import React from 'react';
import { Carousel } from '@mantine/carousel';
import FeaturedCard from '../FeaturedCard/FeaturedCard';
import './ExploreSection.css';

import breakfastImg from '../../img/breakfastFeatureThumbnail.png';
import lunchImg     from '../../img/lunchFeatureThumbnail.png';
import dinnerImg    from '../../img/dinnerFeatureThumbnail.png';
import snacksImg    from '../../img/snackBakingFeatureThumbnail.png';

const FEATURES = [ /* … your array … */ ];

export default function ExploreSection() {
    return (
        <section className="explore-section">
            <h2>Explore</h2>

            {/* Desktop: flex grid; Tablet and below: carousel */}
            <div className="card-container desktop-only">
                {FEATURES.map(r =>
                    <FeaturedCard key={r.subtitle} {...r} />
                )}
            </div>

            <div className="carousel-only">
                <Carousel
                    slideSize="33.333%"      // show 3 across on large tablets
                    slideGap="1rem"
                    align="start"
                    withControls={false}
                    withIndicators
                    breakpoints={[
                        { maxWidth: 'lg', slideSize: '50%' },   // ≤ 1024px → 2 cards
                        { maxWidth: 'md', slideSize: '100%' },  // ≤ 768px → 1 card
                    ]}
                >
                    {FEATURES.map(r =>
                        <Carousel.Slide key={r.subtitle}>
                            <FeaturedCard {...r} />
                        </Carousel.Slide>
                    )}
                </Carousel>
            </div>
        </section>
    );
}
